const products={
 datastream:{name:'Datastream',label:'持续拿到业务库的变化',tech:'无服务器 CDC 与复制服务。持续读取 Oracle、MySQL、PostgreSQL、SQL Server、MongoDB、Spanner、Salesforce 等来源的变更，可写入 Cloud Storage，并可接续 Dataflow 模板。',docs:'https://cloud.google.com/datastream/docs',price:'https://cloud.google.com/datastream/pricing'},
 transfer:{name:'Storage Transfer Service',label:'搬运大批文件和历史数据',tech:'在本地文件系统、HDFS、Amazon S3、Azure Blob、Cloud Storage 和 URL 列表之间传输或定时同步数据。官方说明其针对超过 1 TiB 的传输优化。',docs:'https://cloud.google.com/storage-transfer/docs/overview',price:'https://cloud.google.com/storage-transfer-service#pricing'},
 pubsub:{name:'Pub/Sub',label:'让多个系统收到同一件事',tech:'异步发布/订阅消息服务，通过 topic 与 subscription 解耦生产者和消费者，常用于事件接入并与 Dataflow 集成。',docs:'https://cloud.google.com/pubsub/docs/overview',price:'https://cloud.google.com/pubsub/pricing'},
 kafka:{name:'Managed Service for Apache Kafka',label:'托管现有 Kafka',tech:'托管开源 Apache Kafka 集群，支持 Kafka Connect；适合希望保留 Kafka 应用与跨环境可移植性的团队。',docs:'https://cloud.google.com/managed-service-for-apache-kafka/docs/overview',price:'https://cloud.google.com/managed-service-for-apache-kafka/pricing'},
 dataflow:{name:'Dataflow',label:'实时或批量地整理海量数据',tech:'基于 Apache Beam 的全托管批流处理服务。可用 SDK、模板或 Job Builder 创建管道；支持自动扩缩容。',docs:'https://cloud.google.com/dataflow/docs/overview',price:'https://cloud.google.com/dataflow/pricing'},
 spark:{name:'Managed Service for Apache Spark',label:'运行已有 Spark / Hadoop 作业',tech:'Dataproc 与 Serverless for Apache Spark 已统一到该产品。可选择无服务器 Spark 作业或托管集群，支持 Spark、Hadoop、Hive 等生态。',docs:'https://cloud.google.com/products/managed-service-for-apache-spark',price:'https://cloud.google.com/products/managed-service-for-apache-spark/pricing'},
 fusion:{name:'Cloud Data Fusion',label:'用可视化方式拼出数据流程',tech:'基于 CDAP 的托管数据集成服务。以 DAG 和连接器组合来源、转换、目标，支持预览、调度、触发和版本管理。',docs:'https://cloud.google.com/data-fusion/docs/concepts/overview',price:'https://cloud.google.com/data-fusion/pricing'},
 airflow:{name:'Managed Service for Apache Airflow',label:'让多项任务按顺序自动完成',tech:'原 Cloud Composer。托管 Apache Airflow，以 Python DAG 定义任务依赖、调度和重试，特别适合 ETL/ELT 编排。',docs:'https://cloud.google.com/composer/docs/composer-3/composer-overview',price:'https://cloud.google.com/composer/pricing'},
 dataform:{name:'Dataform',label:'把 SQL 转换变成可测试的代码',tech:'面向 BigQuery 的 ELT 转换开发服务，管理 SQLX/SQL、依赖、Git、断言、文档与调度。Dataform 服务免费，BigQuery 查询和 Logging 等关联服务另计。',docs:'https://cloud.google.com/dataform/docs/overview',price:'https://cloud.google.com/dataform/pricing'},
 catalog:{name:'Knowledge Catalog',label:'弄清数据是什么、能不能信',tech:'原 Dataplex Universal Catalog。发现和管理资产的技术元数据、业务术语、血缘、质量与关系；现有 Dataplex API 和命令继续可用。',docs:'https://cloud.google.com/dataplex/docs/introduction',price:'https://cloud.google.com/products/knowledge-catalog/pricing'},
 metastore:{name:'Dataproc Metastore',label:'让 Spark/Hive 共用同一份表定义',tech:'托管 Apache Hive Metastore，管理 schema、分区、列统计等数据湖技术元数据，为 Spark、Hive、Presto 等引擎提供互操作。',docs:'https://cloud.google.com/dataproc-metastore/docs/overview',price:'https://cloud.google.com/dataproc-metastore/pricing'}
};
const problems=[
 {id:'fresh',title:'我看见的数据总是太旧',hint:'订单、库存或客户信息变了，但报表还没更新',answer:'先确认：您要的是“实时看到变化”，还是“每天固定时间更新一次”。实时的业务变化通常从数据库变更或业务事件开始接入，然后再进行整理。',steps:[['先确定时间要求','是几秒、几分钟，还是隔天更新即可？'],['再确定数据从哪来','来自业务数据库，还是应用/设备发出的事件？'],['最后整理成可用结果','例如把订单变化汇总成门店库存或销售看板。']],tools:['datastream','pubsub','dataflow']},
 {id:'scattered',title:'数据散在文件、系统和别的云里',hint:'每次做分析都要人工找文件、拷数据、对格式',answer:'先不要急着做大平台。把要搬的数据列清楚：在哪里、多久搬一次、搬完放哪。先让数据稳定到达，再谈复杂加工。',steps:[['盘点来源','本地文件、HDFS、其他云对象存储，还是不同业务系统？'],['选搬运方式','大批文件适合专门的传输服务；系统间数据可用集成流程。'],['建立重复执行机制','避免每次靠人手拷贝和改格式。']],tools:['transfer','fusion','spark']},
 {id:'manual',title:'每天都有人盯着流程，还是经常失败',hint:'今天导数、明天跑脚本、后天发现报表没更新',answer:'问题通常不在“会不会跑”，而在“有没有一个人也能看懂、失败也能恢复的流程”。先把谁先谁后、失败找谁写清楚。',steps:[['写出顺序','例如：取数 → 整理 → 检查 → 发布。'],['设定触发与提醒','每天几点跑、上一步失败时谁收到通知。'],['把转换规范化','把关键 SQL 和检查规则放到可追踪的代码流程里。']],tools:['airflow','dataform','fusion']},
 {id:'trust',title:'同一个业务数字，大家算出来不一样',hint:'不知道哪张表可信、口径是什么、数据是否完整',answer:'这首先是“可信度”和“责任归属”问题，不是单纯的技术问题。要能回答：这是什么数据、谁负责、从哪里来、多久更新、质量怎么样。',steps:[['定业务名称与口径','例如“活跃客户”到底指什么？'],['查来源和流转','这张表从哪个系统来，中间经过了什么？'],['自动检查质量','缺失、重复、过期时要让团队知道。']],tools:['catalog','dataform','metastore']},
 {id:'legacy',title:'我们已经有 Kafka 或 Spark，不想推倒重来',hint:'团队已有代码和经验，只想少管集群、少改应用',answer:'这不是落后的选择。关键是先区分：哪些现有资产必须保留，哪些运维工作可以交出去。选型重点变成兼容性、迁移风险和控制程度。',steps:[['盘点已有资产','现有 producer/consumer、Spark 作业、依赖库和运维习惯。'],['决定保留什么','保留 Kafka/Spark 的开发体验，还是换成更无服务器的模型？'],['分阶段迁移','先把一条低风险链路跑通，再扩大范围。']],tools:['kafka','spark','metastore']}
];
const problemGrid=document.querySelector('#problem-grid');
problemGrid.innerHTML=problems.map(p=>`<button class="problem" data-id="${p.id}"><strong>${p.title}</strong><span>${p.hint}</span></button>`).join('');
function renderAnswer(id){const p=problems.find(x=>x.id===id);document.querySelectorAll('.problem').forEach(x=>x.classList.toggle('selected',x.dataset.id===id));const box=document.querySelector('#answer');box.className='answer show';box.innerHTML=`<div class="answer-head"><span class="answer-mark">✓</span><h3>建议先这样聊</h3></div><p>${p.answer}</p><div class="next-steps">${p.steps.map((x,i)=>`<div class="next-step"><b>第 ${i+1} 步</b><strong>${x[0]}</strong><br>${x[1]}</div>`).join('')}</div><p class="solution-tools"><strong>需要知道对应服务？</strong>${p.tools.map(id=>`<button class="tool-button" data-tool="${id}">${products[id].name}</button>`).join('')}</p>`;}
problemGrid.addEventListener('click',e=>{const b=e.target.closest('[data-id]');if(b)renderAnswer(b.dataset.id)});
renderAnswer('fresh');
function card(id){const x=products[id];return `<details class="expert-card" id="${id}"><summary>${x.name}<small>${x.label}</small></summary><div class="expert-body"><p>${x.tech}</p><div class="expert-links"><a href="${x.docs}" target="_blank" rel="noopener">官方文档</a><a href="${x.price}" target="_blank" rel="noopener">官方定价</a></div></div></details>`}
document.querySelector('#expert-list').innerHTML=Object.keys(products).map(card).join('');
document.addEventListener('click',e=>{const tool=e.target.closest('[data-tool]');if(!tool)return;const item=document.querySelector(`#${tool.dataset.tool}`);document.querySelector('#expert').scrollIntoView({behavior:'smooth'});item.open=true;setTimeout(()=>item.scrollIntoView({behavior:'smooth',block:'center'}),280)});
